1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = {
41	  premium: number;
42	};
43	
44	export type ClaimResult = {
45	  payout: number;
46	  remainingCap: number;
47	};
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioResult = {
52	  results: StepResult[];
53	};
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const INSURANCE_VALUES: Record<string, number> = {
68	  sword: 1000,
69	  amulet: 600,
70	  staff: 800,
71	  potion: 400,
72	  rune: 250,
73	  moonstone: 250,
74	};
75	
76	const DEDUCTIBLE_PER_DAMAGE = 100;
77	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
78	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
79	const CAP_MULTIPLIER = 2;
80	
81	const CURSE_SURCHARGE_RATE = 0.5;
82	const HIGH_ENCHANTMENT_THRESHOLD = 5;
83	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
84	const LOYALTY_YEARS_THRESHOLD = 2;
85	const LOYALTY_DISCOUNT_RATE = 0.2;
86	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
87	
88	const BLOCK_SIZE = 3;
89	const BLOCK_BASE_PREMIUM = 60;
90	
91	const basePremiumForType = (type: string): number => BASE_PREMIUMS[type];
92	
93	const itemBasePremium = (item: Item): number => basePremiumForType(item.type);
94	
95	const countByType = (items: Item[]): Map<string, number> => {
96	  const counts = new Map<string, number>();
97	  for (const item of items) {
98	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
99	  }
100	  return counts;
101	};
102	
103	// A block is exactly BLOCK_SIZE alike items, charged as one unit.
104	const formsBlock = (count: number): boolean => count === BLOCK_SIZE;
105	
106	const groupBasePremium = (type: string, count: number): number =>
107	  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * basePremiumForType(type);
108	
109	const policyBasePremium = (items: Item[]): number =>
110	  [...countByType(items)].reduce(
111	    (total, [type, count]) => total + groupBasePremium(type, count),
112	    0,
113	  );
114	
115	// The MHPCO rounds in its own favour: premiums up, payouts down.
116	const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
117	
118	// Item-scoped surcharge clauses. Each applies, independently and additively,
119	// to the affected item's own base premium.
120	const ITEM_SURCHARGE_CLAUSES: {
121	  applies: (item: Item) => boolean;
122	  rate: number;
123	}[] = [
124	  {
125	    applies: (item) => item.cursed === true,
126	    rate: CURSE_SURCHARGE_RATE,
127	  },
128	  {
129	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
130	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
131	  },
132	];
133	
134	const itemSurcharge = (item: Item): number => {
135	  const base = itemBasePremium(item);
136	
137	  return ITEM_SURCHARGE_CLAUSES.filter((clause) => clause.applies(item)).reduce(
138	    (total, clause) => total + base * clause.rate,
139	    0,
140	  );
141	};
142	
143	const itemSurcharges = (items: Item[]): number =>
144	  items.reduce((total, item) => total + itemSurcharge(item), 0);
145	
146	// Everything a policy-scoped clause may inspect.
147	type Policy = {
148	  items: Item[];
149	  customer: Customer;
150	  isFollowUpContract: boolean;
151	};
152	
153	// Policy-scoped modifier clauses. Each applies, independently and additively,
154	// to the policy base premium. A negative rate is a discount.
155	const POLICY_MODIFIER_CLAUSES: {
156	  applies: (policy: Policy) => boolean;
157	  rate: number;
158	}[] = [
159	  {
160	    applies: () => true,
161	    rate: FIRST_INSURANCE_SURCHARGE_RATE,
162	  },
163	  {
164	    applies: (policy) =>
165	      policy.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
166	    rate: -LOYALTY_DISCOUNT_RATE,
167	  },
168	  {
169	    applies: (policy) => policy.isFollowUpContract,
170	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
171	  },
172	];
173	
174	const policyModifiers = (policy: Policy, policyBase: number): number =>
175	  POLICY_MODIFIER_CLAUSES.filter((clause) => clause.applies(policy)).reduce(
176	    (total, clause) => total + policyBase * clause.rate,
177	    0,
178	  );
179	
180	const quote = (policy: Policy): QuoteResult => {
181	  const policyBase = policyBasePremium(policy.items);
182	  const modifiedPremium =
183	    policyBase + itemSurcharges(policy.items) + policyModifiers(policy, policyBase);
184	
185	  return {
186	    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
187	  };
188	};
189	
190	const insuranceSum = (items: Item[]): number =>
191	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
192	
193	// A policy issued by a quote step, tracked so later claims can draw on its cap.
194	type IssuedPolicy = {
195	  items: Item[];
196	  remainingCap: number;
197	};
198	
199	// The cap a fresh policy starts with: a multiple of the insured items' value,
200	// independent of any premium modifiers.
201	const issuePolicy = (items: Item[]): IssuedPolicy => ({
202	  items,
203	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
204	});
205	
206	// Reimbursement clauses read the damaged item, so a claim resolves each
207	// damage entry back to the insured item it refers to.
208	const reimbursedAmount = (item: Item, amount: number): number =>
209	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
210	    ? amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
211	    : amount;
212	
213	// Each damaged item carries its own deductible.
214	const payoutForIncident = (incident: Incident, items: Item[]): number =>
215	  incident.damages.reduce((total, damage) => {
216	    const item = items.find((candidate) => candidate.type === damage.itemType)!;
217	
218	    return total + reimbursedAmount(item, damage.amount) - DEDUCTIBLE_PER_DAMAGE;
219	  }, 0);
220	
221	// A claim draws its payout down from the policy's remaining cap, so the
222	// policy carries less cover into any later claim against it.
223	const drawDownCap = (policy: IssuedPolicy, payout: number): IssuedPolicy => ({
224	  ...policy,
225	  remainingCap: policy.remainingCap - payout,
226	});
227	
228	export const runScenario = (scenario: Scenario): ScenarioResult => {
229	  let hasIssuedContract = false;
230	  const policies = new Map<number, IssuedPolicy>();
231	
232	  const results = scenario.steps.map((step, index): StepResult => {
233	    if (step.op === "claim") {
234	      const issued = policies.get(step.policy)!;
235	      const payout = payoutForIncident(step.incident, issued.items);
236	      const policy = drawDownCap(issued, payout);
237	      policies.set(step.policy, policy);
238	
239	      return { payout, remainingCap: policy.remainingCap };
240	    }
241	
242	    policies.set(index, issuePolicy(step.items));
243	
244	    const result = quote({
245	      items: step.items,
246	      customer: scenario.customer,
247	      isFollowUpContract: hasIssuedContract,
248	    });
249	    hasIssuedContract = true;
250	
251	    return result;
252	  });
253	
254	  return { results };
255	};
